using DomainModel.Models; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DomainModel.Configurations; public class HeroBannerConfiguration:IEntityTypeConfiguration<HeroBanner>{ public void Configure(EntityTypeBuilder<HeroBanner>b){ b.HasKey(x=>x.HeroBannerID); b.Property(x=>x.Title).HasMaxLength(200); b.Property(x=>x.Subtitle).HasMaxLength(500); b.Property(x=>x.ImagePath).HasMaxLength(500); b.Property(x=>x.LinkUrl).HasMaxLength(500); b.Property(x=>x.ButtonText).HasMaxLength(100); b.HasIndex(x=>new{x.IsActive,x.SortOrder}); }}